HELP_TOPICS = {'mode_border_plate': {'title': 'Grondform: Kader (Border) vs. Plack / Inlay (Plate)', 'short': 'Wiessele tëscht engem oppenen Billerkader (Border) an enger duerchgehender Metall- oder Glasplack (Plate).', 'detail': '• KADER (Border): D’Mëtt bleift op (transparent), fir Äert Foto oder Motiv anzefassen.\n• PLACK / INLAY (Plate): D’Mëtt gëtt als massiv, gebürsteten oder halleftransparent Metall-/Glasspigel oder als faarwegt Inlay-Bett ausgefëllt (ideal fir Logoen, Badges & Schëlter).'}, 'grow_direction': {'title': 'Wuess-Richtung (No baussen, No bannen, Mëtt)', 'short': 'Steiert, ob de Kader vun der Auswiel no baussen, no bannen oder zentréiert wiisst.', 'detail': '• No baussen (Bild vergréisseren): De Kader gëtt baussent der Auswiel opgebaut. Wann de Rand net duergeet, vergréissert Borderlay automatesch d’GIMP-Leinwand.\n• No bannen: De Kader wiisst vum Auswielrand a Richtung Zentrum.\n• Béides (zentréiert): De Kader setzt sech 50 % no baussen a 50 % no bannen op d’Auswielkant.'}, 'corner_radii': {'title': 'Ecken & Radien (Bausse- a Banneradius)', 'short': 'Bestëmmt d’Ofrënnung vun de baussenzegen a bannenzegen Kadersäiten (0 px = schaarf 45°-Gehrung).', 'detail': '• Mëll / Mëttel / Dezenter (Radius > 0 px): Erstellt konzentresch gerënnt Ecken wéi eng gestanzt Metallplack.\n• 45°-Gehrung (0 / 0 px): Erstellt e klassesche Kader mat schaarfen 90°-Ecken an echte 45°-Gehrungsnéit.\n• Am Reiter « 2. Geometrie, Radien & 3D » kënne Bausse- a Banneradius getrennt a Pixel ugepasst ginn.'}, 'shape_toolbox': {'title': 'Auswiel-Formen & Ausrichtung', 'short': 'Setzt eng Form als Auswiel a riicht se aus. Et gëtt kee Kader gerendert.', 'detail': '• Uewen d’Kategorie antippen. All Form ass eng Kachel mat hirer Kennung drënner (z. B. leaf.heart), déi een och ënnert der grousser Virschau markéiere kann.\n• Gréisst, Wénkel a Parameter zeechnen d’Form direkt faarweg an d’Bild.\n• Iwwerhuelen hëlt d’Faarf ewech a setzt d’Auswiel. Zoumaachen ouni Iwwerhuelen stellt déi viregt Auswiel erëm hier.\n• Look weist Grondformen, eng Well an e Laachen.\n• Atelier an Team weisen zousätzlech Flamen, Zännrieder, Blieder, Ornament, Fest, Béi, Welle-Parameter, Zwinkeren an de Virwénkel.\n• Eng rechteckeg Auswiel ass de Kader: d’Form start mëttig dran a sengem Säiteverhältnis. Ouni Auswiel start se an der Bildmëtt bei ronn 60 % vun der méi kuerzer Säit.\n• Ausriichten setzt d’Form un dee Kader; d’Feiler réckelen se ëm d’Schrëttwäit, och iwwer de Kader eraus. D’Form wandert, keng Ebene.'}, 'shape_rotation': {'title': 'Auswielform dréinen (Wénkel & 9-Punkt-Dréiachs)', 'short': 'Dréint nëmmen d’Auswielform ëm de gewielten Dréipunkt — d’Bild drënner bleift onberéiert!', 'detail': '• Dréiwénkel (-180° bis +180°): Rotéiert d’Geometrie vum Kader oder der Plack.\n• Blat: Spëtzt uewen, Still ënnen. Dréiachs « Kant ënnen Mëtt » leet de Still an d’Mëtt vun der Rosett.\n• Dréiachs (Pivot): Bestëmmt de Fixpunkt (Zentrum, Eck uewen lénks, asw.).\n• Wichteg: Äert Motiv gëtt NET gedréint, an d’global Luucht bleift physikalesch konsistent!'}, 'repeat_rotation': {'title': 'Méifach-Rotatioun (Startwénkel 1 -> Endwénkel 2, Schrëtt & Fade)', 'short': 'Erstellt automatesch eng gedréint Serie (Fächer / Kaleidoskop) mat schrëttweiser Transparenz.', 'detail': '• Startwénkel 1 & Endwénkel 2 (°): Bestëmmt de Wénkelberäich fir d’Widderhuelung.\n• Rotatiounsschrëtt (°): Setzt den Ofstand tëscht Kopien (z. B. all 15°).\n• Duerchleef: Widderhëlt den Zyklus mat liichtem Versatz a weiderem Fade.\n• Grenz: d’Schalter Duerchleef a Bis Wénkel. Et gëllt een. Deen anere Reegler kënnt mat engem Klick zréck. Bis Wénkel leeft vum Start bis héchstens ±360°.\n• Fade-Schrëtt (%): Blend d’Deckkraaft vun der éischter Kopie (100 %) bis bei déi lescht aus!'}, 'inlay_color': {'title': 'Glas- & Inlay-Faarf (inkl. Pipett & Faarfkachelen)', 'short': 'Bestëmmt d’Eegeschaftsfaarf fir « Faarwegt Kristallglas » souwéi Inlay-Rillen an Inlay-Placken.', 'detail': 'Wou wierkt dës Faarf?\n1. Bei « Faarwegt Kristallglas » fierft se de ganze Glaskierper.\n2. Bei « Verdiefter faarweger Inlay-Muld » am Plackemodus fierft se de bannensten Spigel.\n3. Am Multi-Zonen-Editor fierft se all Zon mat Material « Inlay-Faarf (inlay) ».\n\nTipp: Klickt op de breede Faarfbalken fir Faarfrad a Pipett oder wielt eng vun den 8 Edelsteen-Kachelen.'}, 'metal_gradient': {'title': 'Metall-Verlaf & Iwwerganksbreet', 'short': 'Wielt tëscht der physikalescher 7-Stützpunkt-Kurv an nativen GIMP-Verleef.', 'detail': '• Intern 7-Punkt Materialkurv (recommandéiert): Berechent déi physikalesch Liicht-/Schietkurv fir all Metall.\n• GIMP-Verlaf: Ersetzt d’Metallkurv duerch en eegene GIMP-Verlaf.\n• D’Iwwerganksbreet gëtt iwwer « Fasemëllheet (%) » agestallt.'}, 'dual_profile_cut': {'title': 'Interaktive Profilschnëtt & Iwwerganksbreet', 'short': 'Weist live am Querschnëtt, wou Zonefaarwen, Rillen, Plack-Deckkraaft an Iwwergäng wierken.', 'detail': '• De Schnëtt weist den Héichteprofil vum baussenzege Rand (lénks) bis bei déi bannenzeg Zon (riets).\n• Riets gesitt Dir direkt, ob d’Mëtt op ass oder eng Plack mat der gewielter Deckkraaft huet.\n• Déi giel Bänner weisen déi aktiv Iwwerganksbreet (« Fasemëllheet »).\n• Am Reiter 5 klickt Dir direkt op Z1..Zn am Diagramm fir d’Zonenzeil drënner ze fokusséieren!'}, 'light_vector': {'title': '2D-Liichtvektor, Quellentyp (Strahl vs. Kegel) & Auftreffpunkt', 'short': 'Steiert graphesch Liichtquell -> Auftreffpunkt, Wénkel (°), Intensitéit (%) an Strahlbreet / Kegelduerchmiesser.', 'detail': '• Zitt am 2D-Pad vum giele Liichtpunkt op de Zielpunkt:\n  - D’Richtung setzt den Afallswénkel (0°–360°, Standard 135° = Uewen-Lénks).\n  - D’Längt steiert d’Glanz-Intensitéit (%).\n• Liichtkegel (Cone): Punkt-Spotlight mat Kegelduerchmiesser (%).\n• Liichtstrahl (Beam): Lineare Liichtsträif mat Strahlbreet (%).'}, 'inner_shimmer': {'title': 'Konturfolgenden Bannen-Schimmer', 'short': 'Wërft e mëllen metallesche Liichtglanz vum bannensten Kadrerand an d’Bildmëtt.', 'detail': 'De Banne-Schimmer leeft laanscht déi bannenzegst Kontur a ka sech no der Haaptluucht, uewen lénks, ënnen riets oder ronderëm ausriichten.'}, 'surface_finish': {'title': 'Uewerflächen-Finish: Gebiirscht, Kéierung, Fiederen, Fell & Schuppen', 'short': 'Steiert d’Struktur vu Spigelnd a Satin iwwer Gebiirscht a Kéierung bis Fiederen, Fell a Schuppen.', 'detail': '• Spigelnd / Satin: glat spigelnd oder mëll satinéiert.\n• Gebiirscht: fein geriichte Schleiflinne mat Kéierung a Wénkel.\n• Kéierung: gläichméisseg Mikro-Kéierung ouni Biirschtrichtung.\n• Fiederen, Fell a Schuppen: organesch Muster mat Gréisst, Längt, Dicht a Richtung.\n• Richtung „Follegt dem Liicht“ (-1) oder e feste Wénkel (0° = riets).'}, 'lighting_glow': {'title': 'Liichteffekter, Glanz & Schéin (Bloom)', 'short': 'Steiert automatescht Liicht, Glanzkanten, mëlle Schéin (Bloom), Fasen-Kontrast a Bannen-Schimmer.', 'detail': '• Liicht: automatesch (ab Community) oder manuelle 2D-Liichtvektor (Kegel/Strahl, Atelier).\n• Glanz & Schéin (Bloom): ginn helle Kanten e mëlle Liichtsaum.\n• Fasen-Kontrast a Bannen-Schimmer: steieren d’Plastik an de bannenste Glanz.'}, 'support': {'title': 'Support', 'short': 'Support gëtt et nëmme fir Look, Atelier an Team.', 'detail': 'Support gëtt et nëmme fir Look, Atelier an Team.\nKontakt: https://www.ready-4-it.com/contact'}}
